CREATE FUNCTION fixture_delivery_failure() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF current_setting('test.fail',true)=TG_TABLE_NAME THEN RAISE EXCEPTION 'injected delivery failure'; END IF; RETURN NEW; END$$;
CREATE TRIGGER fixture_fail_message BEFORE INSERT ON social_messages FOR EACH ROW EXECUTE FUNCTION fixture_delivery_failure();
CREATE TRIGGER fixture_fail_notification BEFORE INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION fixture_delivery_failure();
SELECT set_config('test.fail','notifications',false);
SELECT assert_true(refuses($$SELECT fixture_transfer('40000000-0000-0000-0000-000000000006','20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001')$$,'P0001'),'notification failure aborts transaction');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM fixture_effects WHERE id='40000000-0000-0000-0000-000000000006') AND NOT EXISTS(SELECT 1 FROM chip_ledger WHERE id='40000000-0000-0000-0000-000000000006'),'notification failure leaves no financial effect or journal');
