CREATE TABLE union_settlement_floor(union_id uuid,earliest_period_start timestamptz);
CREATE TABLE ca_settlements(settlement_type text,union_id uuid,state text,external_ref text);
CREATE TABLE settlement_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid,union_id uuid,period_number int,year int,start_at timestamptz,end_at timestamptz,status text,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX fixture_squareup ON settlement_invoices(club_id,period_id,invoice_type) WHERE invoice_type='union_weekly_squareup';
CREATE FUNCTION fn_union_prev_week_start(timestamptz) RETURNS timestamptz LANGUAGE sql AS $$SELECT '2026-09-07T07:00Z'::timestamptz$$;
CREATE FUNCTION fn_union_week_start(timestamptz) RETURNS timestamptz LANGUAGE sql AS $$SELECT '2026-09-14T07:00Z'::timestamptz$$;
CREATE FUNCTION fn_union_setting(uuid,text,numeric) RETURNS numeric LANGUAGE sql AS $$SELECT $3$$;
CREATE FUNCTION fn_next_invoice_number(uuid,timestamptz) RETURNS text LANGUAGE sql AS $$SELECT fn_accounting_next_invoice_number()$$;
CREATE FUNCTION fn_union_eco_adjustment(uuid,timestamptz,timestamptz) RETURNS TABLE(baseline_cash_exact boolean) LANGUAGE sql AS $$SELECT true$$;
CREATE FUNCTION fn_union_club_invoice(uuid,timestamptz,timestamptz) RETURNS TABLE(club_id uuid,club_name text,period_start timestamptz,period_end timestamptz,outstanding numeric,rake_generated numeric,union_fee_kept numeric,rakeback_due numeric,players_won numeric,player_pnl_net numeric,eco_amount numeric,eco_enabled boolean,presettled numeric,settled_in_chips numeric,net_position numeric,direction text)
 LANGUAGE sql AS $$SELECT '20000000-0000-0000-0000-000000000001'::uuid,'Club A',$2,$3,-10.23,100,10,90,0,0,0,false,0,90,-10.23,'club_to_union'$$;
